/**
 * @brief Function to initialize a CPU core to perform specified configuration made on the GUI in GUI.
 * @param handle Pointer to static content of APP configuration.
 * @return INTERRUPT_CONFIG_STATUS_t: Status of initialization.\n
 *   @ref INTERRUPT_CONFIG_STATUS_SUCCESS - on successful initialization.\n
 *   @ref INTERRUPT_CONFIG_STATUS_FAILURE - if initialization fails.\n
 * \par<b>Example Usage</b><br>
 * @code
 * #include "Ifx_Types.h"
 * #include "IfxCpu.h"
 * #include "IfxScuWdt.h"
 * #include "DAVE.h"
 * 
 * IFX_ALIGN(4) IfxCpu_syncEvent g_cpuSyncEvent = 0;
 * 
 * void core0_main(void)
 * {
 *   IfxCpu_enableInterrupts();
 *   IfxScuWdt_disableCpuWatchdog(IfxScuWdt_getCpuWatchdogPassword());
 *   IfxScuWdt_disableSafetyWatchdog(IfxScuWdt_getSafetyWatchdogPassword());
 *   IfxCpu_emitEvent(&g_cpuSyncEvent);
 *   IfxCpu_waitEvent(&g_cpuSyncEvent, 1);
 * 
 *   INTERRUPT_CONFIG_STATUS_t status = INTERRUPT_CONFIG_Init(&INTERRUPT_CONFIG_0);     // Initialization of APP
 *   if (status != INTERRUPT_CONFIG_STATUS_SUCCESS) {
 *     while (1) {
 *       // Implement your code to handle the error here!
 *     }
 *   }
 * 
 *   while (1);
 * }
 * @endcode
 * @note Normally this will be called automatically from DAVE_Init() that are located in corresponding main function.
 */
INTERRUPT_CONFIG_STATUS_t INTERRUPT_CONFIG_Init(INTERRUPT_CONFIG_t *handle);

